package com.esp32.keymapper.access

import android.accessibilityservice.AccessibilityService
import android.content.Intent
import android.provider.Settings
import android.view.accessibility.AccessibilityEvent
import com.esp32.keymapper.core.ControllerHub
import com.esp32.keymapper.core.GesturePoint
import com.esp32.keymapper.overlay.GestureCaptureOverlay

/**
 * Injects the touches generated by the controller and hosts the full screen
 * gesture recording overlay.
 */
class KeyMapperAccessibilityService : AccessibilityService() {

    companion object {
        @Volatile
        var instance: KeyMapperAccessibilityService? = null
            private set

        val isEnabled: Boolean
            get() = instance != null
    }

    private var engine: GestureEngine? = null
    private var captureOverlay: GestureCaptureOverlay? = null

    override fun onServiceConnected() {
        super.onServiceConnected()
        instance = this
        ControllerHub.init(applicationContext)

        val gestureEngine = GestureEngine(this)
        engine = gestureEngine
        ControllerHub.gestures = gestureEngine
        ControllerHub.captureSink = { preselect, result -> showCapture(preselect, result) }

        ControllerHub.log("Accessibility gesture engine ready")
        ControllerHub.notifyState()
    }

    private fun showCapture(preselect: Int?, result: (Int, List<GesturePoint>) -> Unit) {
        if (!Settings.canDrawOverlays(this)) {
            ControllerHub.log("Overlay permission is required to draw gestures")
            return
        }
        captureOverlay?.dismiss()
        captureOverlay = null

        val overlay = GestureCaptureOverlay(this, preselect) { id, points ->
            captureOverlay = null
            if (id != null && points != null && points.size >= 2) {
                result(id, points)
            }
        }
        captureOverlay = overlay
        overlay.show()
    }

    override fun onAccessibilityEvent(event: AccessibilityEvent?) {
        // Not used: the service only performs gestures.
    }

    override fun onInterrupt() {
        engine?.releaseAll()
    }

    override fun onUnbind(intent: Intent?): Boolean {
        teardown()
        return super.onUnbind(intent)
    }

    override fun onDestroy() {
        teardown()
        super.onDestroy()
    }

    private fun teardown() {
        engine?.releaseAll()
        engine = null
        captureOverlay?.dismiss()
        captureOverlay = null

        ControllerHub.gestures = null
        ControllerHub.captureSink = null
        instance = null
        ControllerHub.notifyState()
    }
}
